const text = $input.all()[0].json.candidates[0].content.parts[0].text;
const object = JSON.parse(text);
const jsonText = JSON.stringify(object);
const buffer = Buffer.from(jsonText);

return {
  json: object,
  binary: {
    data: {
      data: buffer.toString('base64'), // データをBase64化
      fileName: 'output.json',
      mimeType: 'application/json',
      fileExtension: 'json'
    }
  }
};
